<section class="container page-section" id="permainan">
	<p><a class="btn btn-outline-secondary" href="<?php echo study_arena_game_url($run['game_type']); ?>"><i class="bi bi-arrow-left me-2" aria-hidden="true"></i><?php echo study_arena_type($run['game_type']); ?></a> · <a href="<?php echo site_url('belajar/arena/riwayat'); ?>">Riwayat</a></p>
	<div class="feature-card"><p class="eyebrow"><?php echo study_arena_type($run['game_type']); ?></p><h1 class="h3"><?php echo html_escape($run['title_snapshot']); ?></h1><p><?php echo study_arena_status($run['status']); ?> · <?php echo $run['deadline_at'] ? 'Tantangan waktu' : 'Tanpa timer'; ?></p>
	<?php if ($error): ?><div class="alert alert-danger" role="alert"><?php echo html_escape($error); ?> <a href="<?php echo site_url('belajar/arena/main/'.$run['id']); ?>">Muat ulang</a></div><?php endif; ?>
	<?php $expired = $run['status'] === 'running' && $run['deadline_at'] && time() >= strtotime($run['deadline_at'].' UTC'); ?>
	<?php if ($run['reading']): ?><details class="border rounded p-3 mb-4"<?php echo $run['position'] === 0 ? ' open' : ''; ?>><summary class="fw-bold">Baca ceritanya</summary><div class="mt-3 lh-lg"><?php echo nl2br(html_escape($run['reading'])); ?></div></details><?php endif; ?>
	<?php if ($run['status'] === 'running'): ?>
		<?php if ($run['deadline_at']): ?><p class="alert alert-info" data-arena-deadline="<?php echo (int) strtotime($run['deadline_at'].' UTC'); ?>" data-server-now="<?php echo time(); ?>">Batas waktu server: <?php echo html_escape(study_format_datetime($run['deadline_at'])); ?>. <span data-arena-clock></span></p><?php endif; ?>
		<?php if ($expired): ?><p>Waktu babak berakhir. Simpan hasil untuk melihat pembahasan; jawaban baru tidak akan menambah hasil.</p><?php echo form_open('belajar/arena/main/'.$run['id']); ?><input type="hidden" name="revision" value="<?php echo (int) $run['revision']; ?>"><button class="btn btn-primary" name="action" value="finish">Simpan hasil akhir</button><?php echo form_close(); ?>
	<?php elseif ($run['game_type'] === 'flashcard'): ?>
	<p>Kartu <?php echo (int) $run['position'] + 1; ?> dari <?php echo (int) $run['question_count']; ?> · <?php echo (int) $run['position']; ?> sudah ditinjau.</p>
	<div class="border rounded p-4 mb-3 text-break" aria-live="polite"><h2 class="h4"><?php echo html_escape($run['card_front']); ?></h2><?php if ($run['card_hint']): ?><details class="mt-3"><summary>Petunjuk</summary><p><?php echo html_escape($run['card_hint']); ?></p></details><?php endif; ?><?php if ($run['card_back'] !== NULL): ?><hr><p class="mb-0" data-card-back><?php echo nl2br(html_escape($run['card_back'])); ?></p><?php endif; ?></div>
		<?php echo form_open('belajar/arena/main/'.$run['id'], array('class' => 'd-flex gap-2 flex-wrap')); ?><input type="hidden" name="revision" value="<?php echo (int) $run['revision']; ?>">
		<?php if ($run['card_back'] === NULL): ?><button class="btn btn-primary" name="action" value="reveal">Buka sisi belakang</button>
	<?php else: ?><input type="hidden" name="action" value="rate"><button class="btn btn-primary" name="value" value="known">Sudah paham</button><button class="btn btn-outline-primary" name="value" value="repeat">Perlu diulang</button><?php endif; ?><?php echo form_close(); ?><p class="small text-secondary mt-3">Tandai sesuai pemahamanmu. Ini bukan tes dan tidak menghasilkan poin penukaran.</p>
	<?php elseif ($run['game_type'] === 'memory'): ?>
	<p aria-live="polite"><?php echo (int) $run['correct_count']; ?> dari <?php echo (int) $run['question_count']; ?> pasangan ditemukan · <?php echo (int) $run['moves']; ?> langkah.</p><p class="small text-secondary">Balik dua kartu. Setelah dua terbuka, memilih kartu berikutnya menutup pasangan yang belum cocok.</p>
		<?php echo form_open('belajar/arena/main/'.$run['id'], array('class' => 'row g-2')); ?><input type="hidden" name="revision" value="<?php echo (int) $run['revision']; ?>"><input type="hidden" name="action" value="flip">
		<?php foreach ($run['board'] as $card): ?><div class="col-6 col-md-3"><button type="submit" class="btn <?php echo $card['matched'] ? 'btn-success' : ($card['text'] !== NULL ? 'btn-outline-primary' : 'btn-primary'); ?> w-100 h-100 p-3 text-break" style="min-height:100px" name="value" value="<?php echo $card['index']; ?>"<?php echo $card['disabled'] ? ' disabled' : ''; ?>><?php echo $card['text'] === NULL ? 'Kartu '.($card['index'] + 1) : html_escape($card['text']); ?><?php if ($card['matched']): ?><span class="d-block small">Cocok</span><?php endif; ?></button></div><?php endforeach; ?><?php echo form_close(); ?>
	<?php else: ?>
	<p>Soal <?php echo (int) $run['position'] + 1; ?> dari <?php echo (int) $run['question_count']; ?><?php if ($run['position'] > 0): ?> · Jawaban sebelumnya sudah disimpan.<?php endif; ?></p><h2 class="h4"><?php echo html_escape($run['prompt']); ?></h2>
		<?php if ($run['letters']): ?><p class="h3 text-break my-4" aria-label="Huruf acak"><?php echo html_escape($run['letters']); ?></p><?php endif; ?>
		<?php if ($run['hint']): ?><details class="mb-3"><summary>Petunjuk pertama</summary><p><?php echo html_escape($run['hint']); ?></p><details><summary>Bantu aku memahami lagi</summary><p><?php echo html_escape($run['hint_deeper']); ?></p></details></details><?php endif; ?>
		<?php echo form_open('belajar/arena/main/'.$run['id']); ?><input type="hidden" name="revision" value="<?php echo (int) $run['revision']; ?>"><input type="hidden" name="action" value="answer">
		<?php if ($run['options']): ?><fieldset class="mb-3"><legend class="h6">Pilih jawabanmu</legend><?php foreach ($run['options'] as $key => $label): ?><div class="form-check border rounded p-3 ps-5 mb-2"><input class="form-check-input" type="radio" name="value" id="option-<?php echo html_escape($key); ?>" value="<?php echo html_escape($key); ?>" required><label class="form-check-label text-break" for="option-<?php echo html_escape($key); ?>"><?php echo html_escape($key.'. '.$label); ?></label></div><?php endforeach; ?></fieldset>
	<?php else: ?><div class="mb-3"><label class="form-label" for="arena-answer">Jawabanmu</label><input class="form-control" id="arena-answer" name="value" maxlength="100" autocomplete="off" spellcheck="false" required<?php echo $run['game_type'] === 'math' ? ' inputmode="numeric" pattern="[0-9]+"' : ''; ?>></div><?php endif; ?><button class="btn btn-primary" type="submit">Simpan & lanjutkan</button><?php echo form_close(); ?>
	<?php endif; ?>
	<details class="mt-4"><summary>Akhiri babak lebih awal</summary><p class="mt-2">Hasil yang sudah disimpan tetap tercatat sebagai babak diakhiri, bukan selesai. Untuk jeda, cukup kembali ke Arena dan lanjutkan nanti.</p><?php echo form_open('belajar/arena/main/'.$run['id']); ?><input type="hidden" name="revision" value="<?php echo (int) $run['revision']; ?>"><button class="btn btn-outline-danger" name="action" value="stop">Ya, akhiri babak ini</button><?php echo form_close(); ?></details>
	<?php else: ?>
	<h2 class="h4">Terima kasih sudah mencoba!</h2>
		<?php if ($run['game_type'] === 'expedition'): ?><div class="alert alert-info"><?php echo ! empty($run['passed']) ? 'Level tuntas. Kamu boleh menjelajahi level berikutnya!' : 'Kamu sudah mencoba. Pelajari pembahasan lalu coba lagi untuk membuka level berikutnya.'; ?> Ambang babak ini: <?php echo (int) $run['passing_score']; ?>%.</div><p><a class="btn btn-outline-primary" href="<?php echo study_arena_game_url('expedition'); ?>">Kembali ke peta ekspedisi</a></p><?php endif; ?>
		<?php if ($run['game_type'] === 'flashcard'): ?><p><?php echo (int) $run['position']; ?> kartu ditinjau; <?php echo (int) $run['correct_count']; ?> ditandai sudah paham pada babak ini. Ini refleksi diri, bukan nilai ujian.</p><h3 class="h5">Tinjauan kartu</h3><ul class="ps-3"><?php foreach ($run['review'] as $item): ?><li class="mb-3"><strong><?php echo html_escape($item['answer']); ?></strong><br><?php echo html_escape($item['prompt']); ?><br><span class="text-secondary"><?php echo $item['submitted'] === 'known' ? 'Sudah paham' : ($item['submitted'] === 'repeat' ? 'Perlu diulang' : 'Belum ditinjau'); ?></span></li><?php endforeach; ?></ul>
	<?php else: ?>
		<?php if ($run['game_type'] === 'memory'): ?><p><?php echo (int) $run['correct_count']; ?> dari <?php echo (int) $run['question_count']; ?> pasangan ditemukan dalam <?php echo (int) $run['moves']; ?> langkah.</p><?php else: ?><p><?php echo (int) $run['correct_count']; ?> jawaban benar dari <?php echo (int) $run['question_count']; ?> soal (<?php echo (int) round($run['correct_count'] * 100 / $run['question_count']); ?>%). Hasil permainan, bukan nilai ujian atau bukti ketuntasan kursus.</p><h3 class="h5">Pelajari kembali</h3><ol class="ps-3"><?php foreach ($run['review'] as $item): ?><li class="mb-3"><strong><?php echo html_escape($item['prompt']); ?></strong><br>Jawabanmu: <?php echo html_escape($item['submitted']); ?> · <?php echo $item['correct'] ? 'Benar' : 'Coba pelajari lagi'; ?><br>Jawaban: <strong><?php echo html_escape($item['answer']); ?></strong><?php if ($item['explanation']): ?><p class="mb-1"><?php echo html_escape($item['explanation']); ?></p><?php endif; ?><?php if ($item['tip']): ?><p class="small text-secondary"><?php echo html_escape($item['tip']); ?></p><?php endif; ?></li><?php endforeach; ?></ol><?php endif; ?>
	<?php endif; ?>
	<p class="small text-secondary">Selesai: <?php echo html_escape(study_format_datetime($run['finished_at'])); ?> · Versi konten <?php echo (int) $run['content_version']; ?>. Riwayat ini tidak berubah saat kamu bermain lagi.</p><a class="btn btn-primary" href="<?php echo study_arena_game_url($run['game_type']); ?>">Pilih set berikutnya</a> <a class="btn btn-outline-primary" href="<?php echo site_url('belajar/arena'); ?>">Permainan lain</a>
	<?php endif; ?></div>
</section>
